using Microsoft.AspNetCore.Razor.TagHelpers;

namespace A11yDefaults.Mvc.TagHelpers;

/// <summary>
/// Opt-in removal of the HTML maxlength attribute generated by MVC's Input and
/// TextArea Tag Helpers. MVC model binding and validation metadata are preserved.
/// </summary>
/// <remarks>
/// Use a11y-allow-overlength="true" alongside asp-for. This helper runs after
/// MVC's Tag Helpers, and never overrides an explicit author-supplied maxlength.
/// Server-side validation remains required; removing maxlength does not change
/// StringLength or MaxLength validation rules.
/// </remarks>
[HtmlTargetElement("input", Attributes = "asp-for,a11y-allow-overlength")]
[HtmlTargetElement("textarea", Attributes = "asp-for,a11y-allow-overlength")]
public sealed class A11yAllowOverlengthTagHelper : TagHelper
{
    private static readonly HashSet<string> SupportedInputTypes = new(StringComparer.OrdinalIgnoreCase)
    {
        "text", "email", "tel", "url", "search", "password"
    };

    [HtmlAttributeName("a11y-allow-overlength")]
    public bool AllowOverlength { get; set; }

    // MVC's form Tag Helpers generate their output first.
    public override int Order => 1000;

    public override void Process(TagHelperContext context, TagHelperOutput output)
    {
        // Never leak the authoring-only attribute into rendered HTML.
        output.Attributes.RemoveAll("a11y-allow-overlength");

        if (!AllowOverlength || context.AllAttributes.ContainsName("maxlength"))
        {
            return;
        }

        if (string.Equals(output.TagName, "input", StringComparison.OrdinalIgnoreCase))
        {
            var type = output.Attributes["type"]?.Value?.ToString() ?? "text";
            if (!SupportedInputTypes.Contains(type))
            {
                return;
            }
        }
        else if (!string.Equals(output.TagName, "textarea", StringComparison.OrdinalIgnoreCase))
        {
            return;
        }

        output.Attributes.RemoveAll("maxlength");
    }
}
